import {config,Round} from './config.js';
import {createReactions} from './reactions.js';
const $=id=>document.getElementById(id), machine=document.querySelector('.machine');
let round=new Round(config.duration),frame,endTimer,transformTimer;
const reactions=createReactions({character:$('character'),robot:$('robot'),arena:$('arena'),machine,effects:$('effects')});
const format=n=>n.toLocaleString('ja-JP');
function image(src,alt){$('robot').onerror=()=>{$('robot').onerror=null;$('robot').src='assets/normal.png';};$('robot').src=src;$('robot').alt=alt;}
function start(){reactions.clear();clearTimeout(endTimer);clearTimeout(transformTimer);cancelAnimationFrame(frame);round=new Round(config.duration);round.start(performance.now());machine.className='machine playing';$('score').textContent='0';$('time').textContent='10.0';$('status').textContent='TAP! TAP! TAP!';$('bubble').textContent='どんどんタップ！';$('message').innerHTML='<strong>らりるれろをタップ！</strong><p>どんな姿になるかな？</p>';$('hint').textContent='キャラクターをタップ ・ PCはスペースキーでもOK';$('character').disabled=false;$('character').classList.remove('idle');$('effects').replaceChildren();image(config.normalImage,'らりるれろをタップ');endTimer=setTimeout(finish,config.duration);tick();$('character').focus({preventScroll:true});}
function tick(){if(round.state!=='playing')return;const left=round.remaining(performance.now());$('time').textContent=(left/1000).toFixed(1);$('timer').style.transform=`scaleX(${left/config.duration})`;if(left<=3000){machine.classList.add('urgent');$('bubble').textContent='ラストスパート！';}if(left<=0){finish();return;}frame=requestAnimationFrame(tick);}
function particle(x,y,text,cls='point'){const effects=$('effects');if(effects.childElementCount>45)effects.firstChild.remove();const el=document.createElement('span');el.className=cls;el.textContent=text;el.style.left=x+'px';el.style.top=y+'px';el.style.setProperty('--dx',(Math.random()-.5)*180+'px');el.style.setProperty('--dy',(-40-Math.random()*120)+'px');effects.append(el);el.addEventListener('animationend',()=>el.remove(),{once:true});setTimeout(()=>el.remove(),900);}
function tap(e){if(round.state!=='playing')return;const now=performance.now();if(!round.remaining(now)){finish();return;}const points=round.tap(now);if(!points)return;$('score').textContent=format(round.score);const position=reactions.tap(1-round.remaining(now)/config.duration,now);particle(position.x,position.y,'+'+points);}
function finish(){if(!round.finish())return;reactions.clear();clearTimeout(endTimer);cancelAnimationFrame(frame);$('character').disabled=true;$('time').textContent='0.0';$('timer').style.transform='scaleX(0)';machine.className='machine transforming';$('bubble').textContent='な、なにかが起きる…！';$('status').textContent='TRANSFORMING…';$('message').innerHTML='<strong>らりるれろが変身中…</strong><p>実験結果をお待ちください。</p>';transformTimer=setTimeout(result,1150);}
function result(){round.state='result';const form=config.selectForm(round.score,config.forms);machine.className='machine result';image(form.image,form.name);$('character').classList.add('idle');$('status').textContent='EXPERIMENT COMPLETE';$('bubble').textContent='今回の変身は…';$('message').replaceChildren();const strong=document.createElement('strong');strong.textContent=form.name+'になった！';const p=document.createElement('p');p.textContent=`${round.taps}回タップ！ 次はどんな姿になる？`;$('message').append(strong,p);$('start').innerHTML='もう一回 <span>↻</span>';$('hint').textContent='この結果をスクリーンショットで残そう！';for(let i=0;i<15;i++)particle(Math.random()*$('arena').clientWidth,80+Math.random()*150,'✦','particle');}
$('start').addEventListener('click',start);$('character').addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();tap(e);});$('character').addEventListener('keydown',e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();if(!e.repeat)tap();}});$('character').addEventListener('contextmenu',e=>e.preventDefault());document.addEventListener('visibilitychange',()=>{if(!document.hidden&&round.state==='playing'&&!round.remaining(performance.now()))finish();});$('character').classList.add('idle');
